    mode = data["rounding"]

    def rounded(numerator):
        if mode == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        base = raw if tax_base == "original" else net
        tax = rounded(base * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = str(event.get("account", "default")) + "|" + str(event.get("currency", "USD"))
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependencies(data):
    from itertools import product

    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    choices = [[None] + list(packages[name]) for name in names]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    best_vector = None
    best_versions = None

    for selection in product(*choices):
        versions = {name: row["version"]
                    for name, row in zip(names, selection) if row is not None}
        valid = True
        for name, bounds in data["roots"].items():
            if name not in versions or not bounds[0] <= versions[name] <= bounds[1]:
                valid = False
                break
        if not valid:
            continue
        if any(name in versions and versions[name] in blocked.get(name, [])
               for name in names):
            continue
        if any(name in versions and versions[name] != version
               for name, version in pins.items()):
            continue

        graph = {name: [] for name in versions}
        for name, row in zip(names, selection):
            if row is None:
                continue
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                if (target not in versions or
                        not dep["min"] <= versions[target] <= dep["max"]):
                    valid = False
                    break
                graph[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        stack = list(data["roots"])
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(graph[name])
        if reachable != set(versions):
            continue

        active, finished = set(), set()

        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(child) for child in graph[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(visit(name) for name in graph):
            continue

        vector = tuple(versions.get(name, -1) for name in names)
        if best_vector is None or vector < best_vector:
            best_vector = vector
            best_versions = versions

    if best_vector is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _quota_intervals(data):
    from itertools import combinations

    jobs = [job for job in data["jobs"]
            if job["id"] not in data.get("blocked", [])]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    k = data["k"]
    best_value = None
    best_ids = None

    for chosen in combinations(jobs, k):
        ids = tuple(sorted(job["id"] for job in chosen))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in chosen:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(chosen, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i]["start"] < ordered[i - 1]["end"]
               for i in range(1, len(ordered))):
            continue
        value = sum(job["value"] for job in chosen)
        if (best_value is None or value > best_value or
                (value == best_value and ids > best_ids)):
            best_value, best_ids = value, ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _temporal_routes(data):
    import heapq

    required = data.get("required", [])
    bit_for = {node: 1 << i for i, node in enumerate(required)}
    full_mask = (1 << len(required)) - 1
    source = data["source"]
    initial_mask = bit_for.get(source, 0)
    start_state = (source, initial_mask, data["coupons"])
    distances = {start_state: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        arrival, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != arrival:
            continue
        if node == data["target"] and mask == full_mask and remaining == 0:
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                duration = max(1, edge["duration"] - edge.get("discount", 0))
                options.append((duration, remaining - 1))
            for duration, next_remaining in options:
                next_time = depart + duration
                if next_time > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit_for.get(next_node, 0)
                next_state = (next_node, next_mask, next_remaining)
                if next_time < distances.get(next_state, float("inf")):
                    distances[next_state] = next_time
                    heapq.heappush(queue, (next_time, *next_state))
    return {"arrival": None}


